import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';

import '../models/window_scene.dart';

/// Short feedback sounds (bundled, procedurally generated by
/// `tool/generate_audio.dart`).
enum Sfx {
  chime('audio/chime.wav', 0.7),
  plink('audio/plink.wav', 0.55);

  const Sfx(this.asset, this.volume);
  final String asset;
  final double volume;
}

abstract interface class AudioService {
  /// Starts/switches the ambient loop, or stops it when [track] is null.
  Future<void> setAmbient(AmbientTrack? track);
  Future<void> play(Sfx sfx);
  Future<void> dispose();
}

/// No-op audio for tests and platforms without an audio backend.
class SilentAudioService implements AudioService {
  @override
  Future<void> setAmbient(AmbientTrack? track) async {}
  @override
  Future<void> play(Sfx sfx) async {}
  @override
  Future<void> dispose() async {}
}

/// audioplayers-backed implementation. Ambient loops mix with the user's own
/// music instead of pausing it.
class AudioPlayersService implements AudioService {
  AudioPlayer? _ambient;
  AudioPlayer? _sfx;
  AmbientTrack? _current;
  bool _contextReady = false;

  Future<void> _ensureContext() async {
    if (_contextReady) return;
    _contextReady = true;
    await AudioPlayer.global.setAudioContext(
      AudioContextConfig(focus: AudioContextConfigFocus.mixWithOthers).build(),
    );
  }

  @override
  Future<void> setAmbient(AmbientTrack? track) async {
    try {
      if (track == null) {
        _current = null;
        await _ambient?.stop();
        return;
      }
      if (_current == track) return;
      await _ensureContext();
      final player = _ambient ??= AudioPlayer(playerId: 'ss_ambient');
      await player.setReleaseMode(ReleaseMode.loop);
      await player.play(AssetSource(track.asset), volume: 0.6);
      _current = track;
    } catch (error) {
      debugPrint('SquirrelStash audio: ambient failed ($error)');
    }
  }

  @override
  Future<void> play(Sfx sfx) async {
    try {
      await _ensureContext();
      final player = _sfx ??= AudioPlayer(playerId: 'ss_sfx');
      await player.stop();
      await player.play(AssetSource(sfx.asset), volume: sfx.volume);
    } catch (error) {
      debugPrint('SquirrelStash audio: sfx failed ($error)');
    }
  }

  @override
  Future<void> dispose() async {
    await _ambient?.dispose();
    await _sfx?.dispose();
  }
}
